//! Simulation of the [UserInfo plugin], which installers such as those generated by CPack use to
//! choose between installing for the current user and installing for all users.
//!
//! [UserInfo plugin]: https://nsis.sourceforge.io/UserInfo_plug-in

use std::borrow::Cow;

use quick_xml::{Reader, events::Event};

/// The file name of the UserInfo plugin.
pub const USER_INFO_DLL: &str = "UserInfo.dll";

/// The user name that `UserInfo::GetName` returns.
const USER_NAME: &str = "User";

/// The account type of the user running the installer, as returned by
/// `UserInfo::GetAccountType`.
#[derive(Copy, Clone, Debug, Default, Eq, PartialEq)]
pub enum AccountType {
    Admin,
    #[default]
    User,
}

impl AccountType {
    /// Returns the account type the installer runs as, which is [`Admin`] if its manifest requires
    /// administrator privileges.
    ///
    /// [`Admin`]: Self::Admin
    pub fn from_manifest(manifest: Option<&str>) -> Self {
        if manifest.is_some_and(requires_administrator) {
            Self::Admin
        } else {
            Self::User
        }
    }

    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Admin => "Admin",
            Self::User => "User",
        }
    }
}

/// Simulates calling `function` in the UserInfo plugin, pushing its result onto the stack.
pub fn call<'data>(function: &str, account_type: AccountType, stack: &mut Vec<Cow<'data, str>>) {
    match function {
        "GetName" => stack.push(Cow::Borrowed(USER_NAME)),
        "GetAccountType" | "GetOriginalAccountType" => {
            stack.push(Cow::Borrowed(account_type.as_str()));
        }
        _ => {}
    }
}

/// Returns `true` if the application manifest's requested execution level is
/// `requireAdministrator`.
fn requires_administrator(manifest: &str) -> bool {
    const REQUESTED_EXECUTION_LEVEL: &str = "requestedExecutionLevel";
    const LEVEL: &str = "level";
    const REQUIRE_ADMINISTRATOR: &str = "requireAdministrator";

    let mut reader = Reader::from_str(manifest);
    loop {
        match reader.read_event() {
            Ok(Event::Start(element) | Event::Empty(element))
                if element.local_name().as_ref() == REQUESTED_EXECUTION_LEVEL =>
            {
                return element
                    .try_get_attribute(LEVEL)
                    .ok()
                    .flatten()
                    .is_some_and(|level| level.value.as_ref() == REQUIRE_ADMINISTRATOR);
            }
            Ok(Event::Eof) | Err(_) => return false,
            _ => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use std::borrow::Cow;

    use indoc::indoc;
    use rstest::rstest;

    use super::{AccountType, call};

    fn manifest(level: &str) -> String {
        format!(
            r#"<?xml version="1.0" encoding="UTF-8" standalone="yes"?><assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0"><trustInfo xmlns="urn:schemas-microsoft-com:asm.v3"><security><requestedPrivileges><requestedExecutionLevel level="{level}" uiAccess="false"/></requestedPrivileges></security></trustInfo></assembly>"#
        )
    }

    #[rstest]
    #[case("requireAdministrator", AccountType::Admin)]
    #[case("highestAvailable", AccountType::User)]
    #[case("asInvoker", AccountType::User)]
    fn account_type_from_manifest(#[case] level: &str, #[case] expected: AccountType) {
        assert_eq!(AccountType::from_manifest(Some(&manifest(level))), expected);
    }

    #[test]
    fn account_type_from_prefixed_manifest() {
        const MANIFEST: &str = indoc! {r#"
            <assembly xmlns="urn:schemas-microsoft-com:asm.v1" xmlns:asmv3="urn:schemas-microsoft-com:asm.v3" manifestVersion="1.0">
                <asmv3:trustInfo>
                    <asmv3:security>
                        <asmv3:requestedPrivileges>
                            <asmv3:requestedExecutionLevel level="requireAdministrator"/>
                        </asmv3:requestedPrivileges>
                    </asmv3:security>
                </asmv3:trustInfo>
            </assembly>
        "#};

        assert_eq!(
            AccountType::from_manifest(Some(MANIFEST)),
            AccountType::Admin
        );
    }

    #[test]
    fn account_type_without_manifest() {
        assert_eq!(AccountType::from_manifest(None), AccountType::User);
    }

    #[rstest]
    #[case("GetName", AccountType::Admin, Some("User"))]
    #[case("GetAccountType", AccountType::Admin, Some("Admin"))]
    #[case("GetAccountType", AccountType::User, Some("User"))]
    #[case("GetOriginalAccountType", AccountType::Admin, Some("Admin"))]
    #[case("Unknown", AccountType::Admin, None)]
    fn call_pushes_result(
        #[case] function: &str,
        #[case] account_type: AccountType,
        #[case] expected: Option<&str>,
    ) {
        let mut stack = Vec::<Cow<str>>::new();
        call(function, account_type, &mut stack);
        assert_eq!(stack.pop().as_deref(), expected);
        assert!(stack.is_empty());
    }
}
